MAX_LIMIT = 200


def _error_code(r: Response) -> str:
    try:
        return json.loads(r.body)["error"]["code"]
    except Exception:
        return ""


def _retry_wait(r: Response, now) -> float:
    default = 2 if r.status == 503 else 1
    value = None
    for k, v in r.headers.items():
        if k.lower() == "retry-after":
            value = v.strip()
    if not value:
        return default
    if value.isdigit():
        return int(value)
    try:
        dt = parsedate_to_datetime(value)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return max(0.0, (dt - now()).total_seconds())
    except Exception:
        return default


def _fetch(transport, path, params, sleep, now) -> Response:
    for attempt in range(4):
        r = transport(path, dict(params))
        if r.status == 200:
            return r
        if r.status in (429, 503) and attempt < 3:
            wait = _retry_wait(r, now)
            if wait > 0:
                sleep(wait)
            continue
        raise ApiError(r.status, _error_code(r))
'''
